import { z } from 'zod';
import { DEFAULT_PAGE_SIZE, MAX_PAGE_SIZE } from '../constants.js';

/** Every id in this system is a UUID generated by the database. */
export const uuidSchema = z.string().uuid('Must be a valid id');

export const idParamSchema = z.object({ id: uuidSchema });
export type IdParam = z.infer<typeof idParamSchema>;

/**
 * Slugs are lowercase kebab-case.  Course lookups accept either a UUID or a
 * slug, so the catalog can use readable URLs while the admin UI uses ids.
 */
export const slugSchema = z
  .string()
  .min(1)
  .max(140)
  .regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/, 'Must be lowercase words separated by hyphens');

export const idOrSlugSchema = z.union([uuidSchema, slugSchema]);

/** Query strings arrive as text, so page numbers are coerced then bounded. */
export const paginationQuerySchema = z.object({
  page: z.coerce.number().int().min(1).default(1),
  pageSize: z.coerce.number().int().min(1).max(MAX_PAGE_SIZE).default(DEFAULT_PAGE_SIZE),
});
export type PaginationQuery = z.infer<typeof paginationQuerySchema>;

export const paginationMetaSchema = z.object({
  page: z.number().int(),
  pageSize: z.number().int(),
  total: z.number().int(),
  totalPages: z.number().int(),
  /**
   * Counts per filter tab, where a list has them — "All 4 · Published 2 ·
   * Drafts 1 · Archived 1" on the instructor's My courses screen.
   *
   * They belong in `meta` rather than `data`: they describe the collection
   * being paged, not the page, and putting them here spares the client a
   * second request per tab just to render the number beside it.
   */
  counts: z.record(z.number().int().min(0)).optional(),
});
export type PaginationMeta = z.infer<typeof paginationMetaSchema>;

/** Successful response envelope.  `meta` is present only on list endpoints. */
export type ApiSuccess<T> = {
  success: true;
  message: string;
  data: T;
  meta?: PaginationMeta;
};

/**
 * Failure envelope.  `code` is a stable machine-readable string the client
 * switches on; `errors` carries per-field messages for form mapping.
 */
export type ApiFailure = {
  success: false;
  message: string;
  code: ErrorCode;
  errors?: Record<string, string[]>;
  /**
   * Correlation id, present on 5xx only.  A 5xx body is deliberately vague
   * about what broke, so this is what lets a user's report be matched to the
   * server log line that holds the stack trace.
   */
  requestId?: string;
};

export type ApiResponse<T> = ApiSuccess<T> | ApiFailure;

export const ERROR_CODES = [
  'VALIDATION_ERROR',
  'UNAUTHENTICATED',
  'INVALID_CREDENTIALS',
  'ACCOUNT_INACTIVE',
  'FORBIDDEN',
  'CSRF_ERROR',
  'NOT_FOUND',
  'CONFLICT',
  'UNPROCESSABLE',
  'RATE_LIMITED',
  'INTERNAL_ERROR',
  /** 503: the API is up but a dependency it needs is not.  Worth retrying. */
  'SERVICE_UNAVAILABLE',
] as const;
export type ErrorCode = (typeof ERROR_CODES)[number];

export const emptyToUndefined = <T extends z.ZodTypeAny>(schema: T) =>
  z.preprocess((value) => (value === '' || value === null ? undefined : value), schema.optional());

/**
 * URL schemas live here, in the module with no domain imports, because both
 * `course.ts` (thumbnails) and `lesson.ts` (video, captions) need them. Having
 * them in `course.ts` created a cycle — `course` imported `lesson` for the
 * lesson summary while `lesson` imported `course` for the URL schema — and at
 * module-init time the later import resolved to `undefined`, which blew up as
 * "Cannot read properties of undefined" the first time anything imported the
 * package. Keeping leaf schemas in a leaf module is what prevents that.
 */
export const httpUrlSchema = z
  .string()
  .trim()
  .url('Enter a valid URL')
  .max(2048)
  .refine((value) => /^https?:\/\//i.test(value), 'URL must start with http:// or https://');

/**
 * Media (thumbnails, video, captions) may be an absolute http(s) URL or a
 * root-relative path. That is what lets the app serve its own thumbnails and
 * caption files from the client bundle instead of hot-linking a third party.
 */
export const mediaUrlSchema = z
  .string()
  .trim()
  .min(1, 'Enter a URL or a path')
  .max(2048)
  .refine(
    (value) => /^https?:\/\//i.test(value) || value.startsWith('/'),
    'Use an http(s) URL, or a path starting with /',
  );
